"""Tests for output writers and canonical model export builders."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from depcycle.graph.graph import Graph
from depcycle.graph.node import Node, NodeType
from depcycle.output.base import (
    IOutputWriter,
    project_label,
    relative_file_path,
)
from depcycle.output.dot import DotWriter
from depcycle.output.html import HtmlWriter
from depcycle.output.json import JsonWriter
from depcycle.output.model import build_export
from depcycle.output.text import TextWriter


def test_project_label_and_relative_file_path(tmp_path: Path) -> None:
    g = Graph()
    assert project_label(g) == "Project"
    assert relative_file_path(g, None) == ""
    assert relative_file_path(g, tmp_path / "foo.py") == "foo.py"

    g._project_root = tmp_path
    assert project_label(g) == tmp_path.name
    file_inside = tmp_path / "src" / "mod.py"
    assert relative_file_path(g, file_inside) == "src/mod.py"

    file_outside = Path("/other/dir/mod.py")
    assert relative_file_path(g, file_outside) == "mod.py"


def test_ioutputwriter_abstract() -> None:
    class SubWriter(IOutputWriter):
        pass

    with pytest.raises(TypeError):
        SubWriter()  # type: ignore[abstract]


def test_build_export_and_cycles() -> None:
    g = Graph()
    a = Node(name="mod_a", node_type=NodeType.LOCAL, file_path=Path("/proj/mod_a.py"))
    b = Node(
        name="mod_b", node_type=NodeType.THIRD_PARTY, file_path=Path("/proj/mod_b.py")
    )
    c = Node(name="mod_c", node_type=NodeType.STDLIB)
    d = Node(name="mod_d", node_type=NodeType.UNKNOWN)

    for n in (a, b, c, d):
        g.add_node(n)

    a.add_dependency(b)
    b.add_dependency(a)

    export = build_export(g)
    assert export.project == "Project"
    assert len(export.nodes) == 4
    assert len(export.edges) == 2
    assert export.summary["total_modules"] == 4
    assert export.summary["local"] == 1
    assert export.summary["third_party"] == 1
    assert export.summary["stdlib"] == 1
    assert export.summary["unknown"] == 1
    assert export.summary["cycles_found"] == 1
    assert export.summary["isolated_modules"] == 2


def test_text_writer(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    g = Graph()
    a = Node(name="a", node_type=NodeType.LOCAL)
    b = Node(name="b", node_type=NodeType.LOCAL)
    g.add_node(a)
    g.add_node(b)
    a.add_dependency(b)
    b.add_dependency(a)

    export = build_export(g)
    writer = TextWriter()

    # stdout
    writer.write(export, dest=None)
    captured = capsys.readouterr()
    assert "cycles_found" in captured.out

    # file dest
    out_file = tmp_path / "summary.json"
    writer.write(export, dest=out_file)
    assert out_file.is_file()
    assert "cycles_found" in out_file.read_text(encoding="utf-8")

    # format_inspection module missing
    assert TextWriter.format_inspection(g, [[a, b, a]], "missing") == {
        "error": "module not found: missing"
    }

    # format_inspection module present
    insp = TextWriter.format_inspection(g, [[a, b, a]], "a")
    assert insp["module"] == "a"
    assert insp["dependencies"] == ["b"]
    assert insp["dependents"] == ["b"]

    # format_cycles
    cyc = TextWriter.format_cycles([[a, b, a]])
    assert cyc == {"cycles": [["a", "b", "a"]]}


def test_json_writer(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    g = Graph()
    a = Node(name="a", node_type=NodeType.LOCAL)
    g.add_node(a)

    export = build_export(g)
    writer = JsonWriter()

    # stdout
    writer.write(export, dest=None)
    captured = capsys.readouterr()
    assert '"schema_version": 2' in captured.out

    # file
    out_file = tmp_path / "sub" / "output.json"
    writer.write(export, dest=out_file)
    assert out_file.is_file()
    data = json.loads(out_file.read_text(encoding="utf-8"))
    assert data["schema_version"] == 2


