def test_html_writer_missing_asset(monkeypatch: pytest.MonkeyPatch) -> None:
    writer = HtmlWriter()

    def raise_err(*args, **kwargs):
        raise FileNotFoundError("asset not found")

    monkeypatch.setattr("depcycle.output.html.files", raise_err)

    g = Graph()
    export = build_export(g)

    with pytest.raises(RuntimeError, match="Required HTML asset is missing"):
        writer.write(export)


def test_build_export_empty_cycles_and_non_enum_type() -> None:
    g = Graph()
    node = Node(name="foo", node_type="custom_type")  # type: ignore[arg-type]
    g.add_node(node)

    # Pass non-closed cycle list [ [Node("a"), Node("b")] ] to trigger names[0] != names[-1] branch
    node_a = Node(name="a")
    node_b = Node(name="b")
    export = build_export(g, cycles=[[node_a, node_b]])
    assert len(export.nodes) == 1
    assert export.nodes[0]["type"] == "custom_type"
    assert export.summary["total_modules"] == 1
    assert export.cycles[0]["nodes"] == ["a", "b", "a"]


def test_dot_writer_unrecognized_type() -> None:
    writer = DotWriter()
    fill, color = writer._node_attributes("unknown_custom")
    assert fill == "#F5F5F5"
    assert color == "#444444"
